mapper.select:
SELECT DISTINCT k.
FROM sys_knowledge k

    INNER JOIN sys_knowledge_tag kt ON k.id = kt.knowledge_id

WHERE 

    AND (k.title LIKE CONCAT('%', #{keyword}, '%')
         OR k.content LIKE CONCAT('%', #{keyword}, '%'))


    AND k.difficulty = #{difficulty}


    AND kt.tag_id = #{tagId}


    AND k.status = #{status}

ORDER BY k.created_at DESC

SELECT k.
FROM sys_knowledge k
WHERE 
  AND k.submit_user_id = #{userId}

    AND k.status = #{status}

ORDER BY k.created_at DESC
